<?php
require __DIR__.'/programaciones-common.php';
$id=prog_id($_GET,'id_plantilla');$session=prog_id($_GET,'sesion_editada');$template=prog_template($id);if($session>(int)$template['num_sesiones'])prog_error('La sesión no pertenece a la programación.');
$level=isset($_GET['nivel'])?prog_id($_GET,'nivel',true):(int)$template['nivel'];if($level>3)prog_error('El nivel no es válido.');
$objectives=app_rows('SELECT * FROM agenda_programacion_objetivos_piscina WHERE nivel=? AND id_objetivo_g<>0 ORDER BY id_objetivo_g,id_objetivo','i',[$level]);
$generals=app_rows('SELECT id_objetivo,nombre_objetivo FROM agenda_programacion_objetivos_piscina WHERE id_objetivo_g=0 ORDER BY id_objetivo');
$activities=app_rows('SELECT a.* FROM agenda_programacion_actividades_piscina a JOIN agenda_programacion_objetivos_piscina o ON o.id_objetivo=a.id_objetivo WHERE o.nivel=? AND o.id_objetivo_g<>0 ORDER BY o.id_objetivo_g,o.id_objetivo,a.id_actividad','i',[$level]);
$byObjective=[];foreach($activities as $a)$byObjective[(int)$a['id_objetivo']][]=$a;
$target=app_value($_GET,'id_actividad');$selected=$target!==''?prog_library_target($target):null;
prog_header('Objetivos y actividades','Biblioteca común de ejercicios de la piscina. Los cambios se aplican a todas las sesiones que los utilizan.');?>
<a class="prog-back" href="editar_plantillas.php?id_plantilla=<?=$id?>&amp;sesion_editada=<?=$session?>">← Volver a la sesión <?=$session?></a>
<?php if(app_value($_GET,'done')!==''){?><p class="prog-notice" role="status">Cambios guardados en la biblioteca.</p><?php }?>
<div class="prog-activity-layout"><section class="prog-panel prog-details"><h2>Editar un objetivo o actividad</h2><form method="get"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><label>Nivel<select name="nivel"><?php for($n=0;$n<4;$n++){?><option value="<?=$n?>" <?=$level===$n?'selected':''?>><?=app_escape(prog_level($n))?></option><?php }?></select></label><button class="prog-button secondary" type="submit">Ver actividades del nivel</button></form>
<form method="get"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="nivel" value="<?=$level?>"><label>Objetivo o actividad<select name="id_actividad" required><option value="">Selecciona para editar</option><?php foreach($objectives as $o){?><optgroup label="<?=app_escape($o['nombre_objetivo'])?>"><option value="O<?=(int)$o['id_objetivo']?>" <?=$target==='O'.$o['id_objetivo']?'selected':''?>>Objetivo: <?=app_escape($o['nombre_objetivo'])?></option><?php foreach($byObjective[(int)$o['id_objetivo']]??[] as $a){?><option value="<?=(int)$a['id_actividad']?>" <?=$target===(string)$a['id_actividad']?'selected':''?>><?=app_escape($a['descripcion_actividad'])?></option><?php }?></optgroup><?php }?></select></label><button type="submit" class="prog-button secondary">Abrir selección</button></form>
<?php if($selected){[$isObjective,$item,$record]=$selected;?><form method="post" action="guarda_actividades_plantilla.php" data-confirm="Este cambio se aplicará a todas las sesiones que utilizan este objetivo o actividad. ¿Guardar?"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="id_actividad" value="<?=app_escape($target)?>"><label>Descripción<textarea name="texto_editado" required rows="5" maxlength="<?=$isObjective?255:5000?>"><?=app_escape($record[$isObjective?'nombre_objetivo':'descripcion_actividad'])?></textarea></label><button class="prog-button" type="submit">Guardar descripción</button></form><form method="post" action="eliminar_actividades_plantilla.php" data-confirm="¿Eliminar de la biblioteca? Solo es posible si no tiene actividades o sesiones asociadas."><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="id_actividad" value="<?=app_escape($target)?>"><button class="prog-button danger" type="submit">Eliminar de la biblioteca</button></form>
<?php if(!$isObjective){?><h3>Imagen de la actividad</h3><?php if(is_file(__DIR__.'/imagenes/'.$item.'.jpg')){?><a href="imagenes/<?=$item?>.jpg" target="_blank" rel="noopener"><img class="prog-activity-image" src="imagenes/<?=$item?>.jpg" alt="Imagen de la actividad seleccionada"></a><?php }else{?><p class="prog-muted">La actividad todavía no tiene una imagen.</p><?php }?><form method="post" action="imagenes/upload.php" enctype="multipart/form-data"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="id_actividad" value="<?=$item?>"><input type="hidden" name="return_html" value="1"><label>Imagen (JPEG o PNG, hasta 8 MB)<input type="file" name="images" accept="image/jpeg,image/png" required></label><button type="submit" class="prog-button secondary">Guardar imagen</button></form><?php }}?></section>
<section class="prog-panel prog-details"><h2>Añadir a <?=app_escape(prog_level($level))?></h2><form method="post" action="nuevo_objetivo_plantilla.php"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><input type="hidden" name="nivel" value="<?=$level?>"><label>Objetivo general<select name="objetivo_nivel" required><option value="">Selecciona el objetivo general</option><?php foreach($generals as $g){?><option value="<?=(int)$g['id_objetivo']?>"><?=app_escape($g['nombre_objetivo'])?></option><?php }?></select></label><label>Nuevo objetivo<input name="objetivo_nuevo" required maxlength="255" placeholder="Escribe el objetivo específico"></label><button class="prog-button secondary" type="submit">Añadir objetivo</button></form><h3>Nueva actividad</h3><form method="post" action="nueva_actividad_plantilla.php"><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="sesion_editada" value="<?=$session?>"><label>Objetivo<select name="objetivo_nueva" required><option value="">Selecciona un objetivo</option><?php foreach($objectives as $o){?><option value="<?=(int)$o['id_objetivo']?>"><?=app_escape($o['nombre_objetivo'])?></option><?php }?></select></label><label>Descripción<textarea name="actividad_nueva" required rows="4" maxlength="5000"></textarea></label><button class="prog-button secondary" type="submit">Añadir actividad</button></form></section></div>
<?php prog_footer(); ?>